def build2():
    buckets=collections.defaultdict(list)
    for c in cands:
        sec='Breaking changes' if c['breaking'] else {'feat':'Features','fix':'Fixes','perf':'Features'}[c['type']]
        buckets[sec].append(c)
    order=['Breaking changes','Features','Fixes']
    lines=['# Release 4.2.0','']
    for sec in order:
        if not buckets[sec]: continue
        groups=collections.defaultdict(list)
        for c in buckets[sec]:
            groups[(c['scope'],c['summary'])].append(c)
        entries=[]
        for (scope,summ),cs in groups.items():
            cs=sorted(cs,key=lambda c:(-c['dt'].timestamp(), c['hash']))
            refs=[]; hashes=[]
            for c in cs:
                for n in c['issues']:
                    if n not in refs: refs.append(n)
                hashes.append(c['key'])
            entries.append(dict(scope=scope,summary=summ,refs=refs,hashes=hashes,newest=cs[0]['dt']))
        entries.sort(key=lambda e:(e['scope'], -e['newest'].timestamp()))
        lines.append(f"## {sec}"); lines.append('')
        for e in entries:
            head=f"- **{e['scope']}:** "
            tail=' ('+', '.join(e['hashes'])+')'
            if e['refs']:
                tail=' ('+', '.join('#'+str(n) for n in e['refs'])+')'+tail
            avail=100-len(head)-len(tail)
            s=e['summary']
            if len(s)>avail:
                s=s[:avail-1].rstrip(' ')+'\u2026'
            line=head+s+tail
            assert len(line)<=100
            lines.append(line)
        lines.append('')
    while lines and lines[-1]=='': lines.pop()
    return lines

for l in build2():
    print(len(l), repr(l) if len(l)>90 else l)

